import{_ as t,o as i,c as a,ae as o}from"./chunks/framework.C4zpkcTP.js";const u=JSON.parse('{"title":"DockPilot wiki","description":"A lightweight wiki for the DockPilot repository.","frontmatter":{"title":"DockPilot wiki","description":"A lightweight wiki for the DockPilot repository."},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),r={name:"index.md"};function l(n,e,s,d,c,h){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="dockpilot-wiki" tabindex="-1">DockPilot wiki <a class="header-anchor" href="#dockpilot-wiki" aria-label="Permalink to &quot;DockPilot wiki&quot;">​</a></h1><p>This is a lightweight wiki for the DockPilot repository. It is meant to help someone orient quickly without reading the whole codebase.</p><h2 id="what-dockpilot-is" tabindex="-1">What DockPilot is <a class="header-anchor" href="#what-dockpilot-is" aria-label="Permalink to &quot;What DockPilot is&quot;">​</a></h2><p>A self-hosted Docker infrastructure control center with:</p><ul><li>a React dashboard,</li><li>a Fastify API,</li><li>PostgreSQL plus Drizzle ORM,</li><li>owner setup and Argon2id authentication,</li><li>revocable server-side sessions,</li><li>an MCP control layer for external AI agents,</li><li>admin-visible AI credentials, audit log, and approvals.</li></ul><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>This is an <strong>alpha</strong>. Some parts are real, some parts are placeholders, and some expected features are not built yet. The dashboard is honest about what is missing instead of pretending Docker hosts are connected.</p><h2 id="what-works-right-now" tabindex="-1">What works right now <a class="header-anchor" href="#what-works-right-now" aria-label="Permalink to &quot;What works right now&quot;">​</a></h2><ul><li>Repository bootstrap, linting, formatting, typechecking, building, and tests.</li><li>One-time owner setup and login.</li><li>Session authentication with revocation.</li><li>Administrator REST routes for system status, AI credentials, audit events, and approvals.</li><li>MCP endpoint with dedicated AI credential authentication, scoped permissions, narrow tools, rate limiting, validation, correlation IDs, and append-only audit logging.</li><li>Human approval flow for destructive requests.</li><li>Adversarial MCP security tests.</li></ul><h2 id="what-is-not-implemented-yet" tabindex="-1">What is not implemented yet <a class="header-anchor" href="#what-is-not-implemented-yet" aria-label="Permalink to &quot;What is not implemented yet&quot;">​</a></h2><ul><li>Docker hosts, agents, containers, images, volumes, networks, container logs, Docker Doctor.</li><li>Agent enrollment and container operations.</li><li>Metrics, backup/restore, notifications, update execution, integrations, automation.</li><li>Multi-organization/multi-tenant administration.</li><li>Password recovery.</li><li>Automatic audit retention.</li></ul><h2 id="repository-layout" tabindex="-1">Repository layout <a class="header-anchor" href="#repository-layout" aria-label="Permalink to &quot;Repository layout&quot;">​</a></h2><ul><li><code>apps/web</code> — React dashboard and same-origin API client.</li><li><code>apps/api</code> — Fastify API, database layer, Drizzle schema/migrations, auth, admin routes, MCP gateway, and shared services.</li><li><code>packages/shared</code> — strict schemas, protocol types, and the MCP tool contract.</li><li><code>infrastructure/compose.yaml</code> — local loopback-only PostgreSQL for development and tests.</li><li><code>docs/</code> — architecture and this wiki.</li><li><code>apps/api/drizzle/</code> — Drizzle migrations and metadata.</li></ul><h2 id="key-services" tabindex="-1">Key services <a class="header-anchor" href="#key-services" aria-label="Permalink to &quot;Key services&quot;">​</a></h2><ul><li>Web app: <code>apps/web</code>.</li><li>API: <code>apps/api/src/server.ts</code>.</li><li>MCP gateway: <code>apps/api/src/mcp</code>.</li><li>Shared service layer: <code>apps/api/src/services</code>.</li><li>MCP tool contract: <code>packages/shared/src/mcp.ts</code>.</li></ul><h2 id="mcp-control-layer-in-one-paragraph" tabindex="-1">MCP control layer in one paragraph <a class="header-anchor" href="#mcp-control-layer-in-one-paragraph" aria-label="Permalink to &quot;MCP control layer in one paragraph&quot;">​</a></h2><p>External AI agents authenticate with dedicated <code>dpai_</code> bearer tokens, not browser sessions. The MCP endpoint is Streamable HTTP at <code>/api/v1/mcp</code>, registered only when <code>MCP_ENABLED</code> is not <code>false</code>. There is a local stdio entry point for development. Tools are narrow and named. There is no shell, SQL, Docker socket, or generic execute tool. Destructive actions do not execute directly; they create pending approvals that an administrator must decide. Every MCP call writes an audit event, even failures.</p><h2 id="authentication-model" tabindex="-1">Authentication model <a class="header-anchor" href="#authentication-model" aria-label="Permalink to &quot;Authentication model&quot;">​</a></h2><ul><li>Humans authenticate with sessions.</li><li>AI agents authenticate with AI credentials.</li><li>Credentials are created by administrators through the admin API.</li><li>The raw token is returned exactly once and never stored in plaintext.</li><li>Only an HMAC-SHA256 digest is persisted, keyed by <code>MCP_TOKEN_SECRET</code>.</li><li>Production refuses to start while MCP is enabled and <code>MCP_TOKEN_SECRET</code> is missing.</li></ul><h2 id="admin-surface" tabindex="-1">Admin surface <a class="header-anchor" href="#admin-surface" aria-label="Permalink to &quot;Admin surface&quot;">​</a></h2><p>Administrator-only routes are under <code>/api/v1/admin</code>:</p><ul><li>system status,</li><li>AI credential create/list/revoke,</li><li>audit event list/detail with filters and pagination,</li><li>approval list and decision.</li></ul><p>The dashboard has an AI control area with the same capabilities.</p><h2 id="security-notes" tabindex="-1">Security notes <a class="header-anchor" href="#security-notes" aria-label="Permalink to &quot;Security notes&quot;">​</a></h2><ul><li>Development Compose file and example passwords are not production deployment instructions.</li><li>Production needs real PostgreSQL, real secrets, HTTPS, secret management, reviewed network policy, and backups.</li><li>Never expose PostgreSQL or Docker sockets to a public interface.</li><li>MCP credentials should be treated as production secrets.</li></ul><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><ul><li>Unit tests cover redaction, rate limiting, pagination, permission ordering, token handling, and the MCP tool contract.</li><li>Integration tests cover real HTTP behavior, MCP authentication and tool execution, approval workflow, cross-organization isolation, privilege escalation, secret non-disclosure, injection resistance, traversal resistance, and audit immutability.</li></ul><h2 id="documentation-pointers" tabindex="-1">Documentation pointers <a class="header-anchor" href="#documentation-pointers" aria-label="Permalink to &quot;Documentation pointers&quot;">​</a></h2><ul><li>Project readme: <a href="https://example.invalid/README.md" target="_blank" rel="noreferrer">README.md</a></li><li>Architecture and threat model: <a href="https://example.invalid/ARCHITECTURE.md" target="_blank" rel="noreferrer">ARCHITECTURE.md</a></li><li>This wiki source: <a href="https://example.invalid/WIKI_HANDOFF.md" target="_blank" rel="noreferrer">WIKI_HANDOFF.md</a></li></ul>',29)])])}const m=t(r,[["render",l]]);export{u as __pageData,m as default};
